def solve(values):
    values=sorted(values); used=[False]*len(values); result=[]
    def visit(path):
        if len(path)==len(values): result.append(path.copy()); return
        for i,value in enumerate(values):
            if used[i] or (i>0 and values[i]==values[i-1] and not used[i-1]): continue
            used[i]=True; path.append(value); visit(path); path.pop(); used[i]=False
    visit([])
    return result
